class NomNomencladores extends BaseNomNomencladores {

    /**
     * Obtener un listado de nomencladores.
     * 
     * @return array Listado de los datos de los nomencladores.
     */
    public static function obtenerTodosNomencladores() {
        //Creando la consulta DQL que devuelve el listado de nomencladores.
        $queryObj = Doctrine_Query::create()
                ->from('NomNomencladores')
				->orderBy('denom');

        //Devolviendo el listado de nomencladores en forma de arreglo.
        return $queryObj->fetchArray();
    }

}